{"operation":"run_python","code":"import mpmath as mp
mp.mp.dps = 50

def O(n):
    return mp.nsum(lambda k: 1/(2*k-1), [1, n])
def B(n):
    return mp.nsum(lambda k: (-1)**(k-1)/(2*k-1), [1, n])

def term(n):
    return (-1)**(n-1)*O(n)*B(n)/(n**2)

# direct partial sum with tail? Use nsum
S = mp.nsum(lambda n: term(n), [1, mp.inf])
print(S)
beta4 = mp.nsum(lambda n: (-1)**(n-1)/(2*n-1)**4, [1, mp.inf])
print(beta4)
G = mp.catalan
pi2G = mp.pi**2*G
print(pi2G)
# ratio
print(S/pi2G)
print(S/beta4)
"}
